pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract InvMutTest is Test {
    airDrop c;
    function setUp() public { c = new airDrop(); }

    function testFuzz_property(address from, address someEOA, uint256 v, uint8 decimals, address[] memory tos) public {
        vm.assume(tos.length > 0);
        vm.assume(from != address(0));
        uint8 d = decimals % 19;

        AdversarialCallee adv = new AdversarialCallee();

        address callee = address(adv);

        bool ok;
        try c.transfer(from, callee, tos, v, d) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract AdversarialCallee {
    fallback() external payable {
        if (msg.data.length >= 4) {
            bytes4 sig;
            assembly { sig := calldataload(0) }
            if (sig == bytes4(keccak256("transferFrom(address,address,uint256)"))) {
                revert("forced revert on transferFrom");
            }
        }
    }
}
